llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Bumetanide, a structurally related sulfamoylbenzoic acid loop diuretic, had absolute oral bioavailability of 0.78 for the tablet and 0.80 for the solution in normal subjects, showing that this polar, ionized acid class can achieve F well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Hydrochlorothiazide, sharing the chlorobenzenesulfonamide motif, showed absolute oral bioavailability of 60.2% in humans, supporting adequate absorption despite polar sulfonamide groups.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Tolfenamic acid, an anthranilic acid with a carboxylic acid and chloro substituent, had absolute oral bioavailability of 60.4% in healthy volunteers, indicating that ionized carboxylic acid drugs can exceed 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Azosemide, the closest direct analogue with a tetrazole bioisostere and thienylmethylamino group, was estimated to have only about 10% oral bioavailability in patients, providing affirmative low-F evidence for a close structural relative.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Although the physicochemical prior is low and the closest azosemide analogue shows low F, multiple structurally related sulfonamide/anthranilic acid diuretics (bumetanide, hydrochlorothiazide, tolfenamic acid) have absolute oral bioavailability of 60-80%, and furosemide itself is known to be absorbed to a clinically useful extent. The weight of transferable experimental evidence supports F >= 20%.",
  "evidence_gaps": [
    "No direct furosemide parent bioavailability record is present in the evidence set; the highest-similarity record is for furosemide acyl glucuronide metabolite exposure, not parent F.",
    "Cystic fibrosis-specific oral bioavailability data for furosemide or close analogues are absent.",
    "Azosemide low bioavailability may reflect analogue-specific first-pass metabolism that is not clearly shared by furosemide."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

